{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C39"],
      "claim": "Bidisomide, which shares the piperidineethyl tertiary-carbinol core, has absolute oral bioavailability of 61% in humans, supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Fexofenadine, a piperidine carbinol P-gp substrate, has absolute oral bioavailability of 33% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Flavoxate, a piperidine ethyl ester, has oral bioavailability close to 100% in healthy volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "R-Desethyloxybutynin, a tertiary carbinol with phenyl/cyclohexyl substitution, has bioavailability of 62% in healthy adults, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Ebastine, a piperidine-containing BCS-II drug, achieves about 40% oral bioavailability, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Terfenadine has <2% oral bioavailability, but this extreme low value is driven by extensive CYP3A4 first-pass metabolism to fexofenadine, a specific liability not mirrored in the query structure.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "Loperamide has 0.3% oral bioavailability due to P-gp efflux and first-pass metabolism; the query lacks the amide/diphenyl features responsible for this extreme liability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Darifenacin has 15% absolute bioavailability at 7.5 mg ER, below the threshold, but its low F is attributed to low solubility and high first-pass metabolism, features less applicable to the more lipophilic query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic basic tertiary amino alcohol with a piperidineethyl carbinol and phenyl/norbornene substituents. Structurally related piperidine carbinol drugs with measured human absolute bioavailability (bidisomide 43-61%, fexofenadine 30-33%, ebastine ~40%, desethyloxybutynin 62-78%, flavoxate ~100%) support F >= 20%. The low-F analogues (terfenadine, loperamide, darifenacin) owe their low bioavailability to specific metabolic/efflux or solubility liabilities that are not clearly present in the query. Therefore, high oral bioavailability at the F >= 20% threshold is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule or its closest named analogue.",
    "The P-gp efflux and first-pass metabolism liability of the query are not experimentally characterized.",
    "Human pharmacokinetic data for the closest structural analogues come from different chemical series with varying metabolic soft spots."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

